(()=>{"use strict";var __webpack_modules__={57:()=>{eval("\n;// ./src/homepage.js\nfunction loadHome() {\r\n    const content = document.getElementById('content');\r\n    \r\n    // Create home container\r\n    const homeContainer = document.createElement('div');\r\n    homeContainer.className = 'home-container';\r\n    \r\n    // Create and add headline\r\n    const headline = document.createElement('h1');\r\n    headline.textContent = 'Welcome to Bella Vista Restaurant';\r\n    \r\n    // Create and add restaurant image\r\n    const image = document.createElement('img');\r\n    image.src = 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=2070&q=80';\r\n    image.alt = 'Beautiful restaurant interior';\r\n    \r\n    // Create and add description\r\n    const description = document.createElement('p');\r\n    description.textContent = 'Experience culinary excellence in the heart of the city. Our restaurant combines traditional recipes with modern techniques to create unforgettable dining experiences. From our carefully curated menu to our warm, welcoming atmosphere, every detail is designed to make your visit special.';\r\n    \r\n    // Append all elements to container\r\n    homeContainer.appendChild(headline);\r\n    homeContainer.appendChild(image);\r\n    homeContainer.appendChild(description);\r\n    \r\n    // Add container to content\r\n    content.appendChild(homeContainer);\r\n}\r\n\n;// ./src/menu.js\nfunction loadMenu() {\r\n    const content = document.getElementById('content');\r\n    \r\n    // Create menu container\r\n    const menuContainer = document.createElement('div');\r\n    menuContainer.className = 'menu-container';\r\n    \r\n    // Create and add headline\r\n    const headline = document.createElement('h1');\r\n    headline.textContent = 'Our Menu';\r\n    menuContainer.appendChild(headline);\r\n    \r\n    // Create menu grid\r\n    const menuGrid = document.createElement('div');\r\n    menuGrid.className = 'menu-grid';\r\n    \r\n    // Menu data\r\n    const menuData = {\r\n        'Appetizers': [\r\n            { name: 'Bruschetta Trio', price: '$12' },\r\n            { name: 'Calamari Fritti', price: '$14' },\r\n            { name: 'Antipasto Platter', price: '$18' },\r\n            { name: 'Stuffed Mushrooms', price: '$11' }\r\n        ],\r\n        'Main Courses': [\r\n            { name: 'Grilled Salmon', price: '$26' },\r\n            { name: 'Ribeye Steak', price: '$32' },\r\n            { name: 'Chicken Parmigiana', price: '$22' },\r\n            { name: 'Vegetarian Pasta', price: '$18' },\r\n            { name: 'Seafood Risotto', price: '$24' }\r\n        ],\r\n        'Desserts': [\r\n            { name: 'Tiramisu', price: '$8' },\r\n            { name: 'Chocolate Lava Cake', price: '$9' },\r\n            { name: 'Panna Cotta', price: '$7' },\r\n            { name: 'Gelato Selection', price: '$6' }\r\n        ]\r\n    };\r\n    \r\n    // Create menu categories\r\n    Object.entries(menuData).forEach(([category, items]) => {\r\n        const categoryDiv = document.createElement('div');\r\n        categoryDiv.className = 'menu-category';\r\n        \r\n        const categoryTitle = document.createElement('h2');\r\n        categoryTitle.textContent = category;\r\n        categoryDiv.appendChild(categoryTitle);\r\n        \r\n        items.forEach(item => {\r\n            const menuItem = document.createElement('div');\r\n            menuItem.className = 'menu-item';\r\n            \r\n            const itemName = document.createElement('span');\r\n            itemName.className = 'menu-item-name';\r\n            itemName.textContent = item.name;\r\n            \r\n            const itemPrice = document.createElement('span');\r\n            itemPrice.className = 'menu-item-price';\r\n            itemPrice.textContent = item.price;\r\n            \r\n            menuItem.appendChild(itemName);\r\n            menuItem.appendChild(itemPrice);\r\n            categoryDiv.appendChild(menuItem);\r\n        });\r\n        \r\n        menuGrid.appendChild(categoryDiv);\r\n    });\r\n    \r\n    menuContainer.appendChild(menuGrid);\r\n    content.appendChild(menuContainer);\r\n}\r\n\n;// ./src/contact.js\nfunction loadContact() {\r\n    const content = document.getElementById('content');\r\n    \r\n    // Create contact container\r\n    const contactContainer = document.createElement('div');\r\n    contactContainer.className = 'contact-container';\r\n    \r\n    // Create and add headline\r\n    const headline = document.createElement('h1');\r\n    headline.textContent = 'Contact Us';\r\n    contactContainer.appendChild(headline);\r\n    \r\n    // Create contact info grid\r\n    const contactInfo = document.createElement('div');\r\n    contactInfo.className = 'contact-info';\r\n    \r\n    // Contact data\r\n    const contactData = [\r\n        {\r\n            title: 'Location',\r\n            content: '123 Gourmet Street<br>Foodie District<br>New York, NY 10001'\r\n        },\r\n        {\r\n            title: 'Phone & Email',\r\n            content: 'Phone: (555) 123-4567<br>Email: info@bellavista.com<br>Reservations: reservations@bellavista.com'\r\n        },\r\n        {\r\n            title: 'Hours',\r\n            content: 'Monday - Thursday: 5:00 PM - 10:00 PM<br>Friday - Saturday: 5:00 PM - 11:00 PM<br>Sunday: 4:00 PM - 9:00 PM'\r\n        }\r\n    ];\r\n    \r\n    // Create contact cards\r\n    contactData.forEach(contact => {\r\n        const contactCard = document.createElement('div');\r\n        contactCard.className = 'contact-card';\r\n        \r\n        const cardTitle = document.createElement('h3');\r\n        cardTitle.textContent = contact.title;\r\n        \r\n        const cardContent = document.createElement('p');\r\n        cardContent.innerHTML = contact.content;\r\n        \r\n        contactCard.appendChild(cardTitle);\r\n        contactCard.appendChild(cardContent);\r\n        contactInfo.appendChild(contactCard);\r\n    });\r\n    \r\n    contactContainer.appendChild(contactInfo);\r\n    content.appendChild(contactContainer);\r\n}\r\n\n;// ./src/index.js\n\r\n\r\n\r\n\r\nconsole.log('Bella Vista Restaurant website is running!');\r\n\r\nconst content = document.getElementById('content');\r\n\r\nfunction clearContent() {\r\n    content.innerHTML = '';\r\n}\r\n\r\nfunction setActiveTab(activeButton) {\r\n    // Remove active class from all buttons\r\n    document.querySelectorAll('nav button').forEach(btn => {\r\n        btn.classList.remove('active');\r\n    });\r\n    // Add active class to clicked button\r\n    activeButton.classList.add('active');\r\n}\r\n\r\n// Load home page initially\r\nclearContent();\r\nloadHome();\r\n\r\n// Get tab buttons\r\nconst homeTab = document.getElementById('home-tab');\r\nconst menuTab = document.getElementById('menu-tab');\r\nconst contactTab = document.getElementById('contact-tab');\r\n\r\n// Add event listeners for tab switching\r\nhomeTab.addEventListener('click', () => {\r\n    clearContent();\r\n    setActiveTab(homeTab);\r\n    loadHome();\r\n});\r\n\r\nmenuTab.addEventListener('click', () => {\r\n    clearContent();\r\n    setActiveTab(menuTab);\r\n    loadMenu();\r\n});\r\n\r\ncontactTab.addEventListener('click', () => {\r\n    clearContent();\r\n    setActiveTab(contactTab);\r\n    loadContact();\r\n});\r\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///57\n")}},__webpack_exports__={};__webpack_modules__[57]()})();